    CopyServerlessCacheSnapshotRequest.add_member(:target_serverless_cache_snapshot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetServerlessCacheSnapshotName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the snapshot to be created. Available for Valkey, Redis OSS and Serverless Memcached only.</p>", "smithy.api#required" => {}}))
