    CopySnapshotMessage.add_member(:source_snapshot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceSnapshotName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of an existing snapshot from which to make a copy.</p>", "smithy.api#required" => {}}))
    CopySnapshotMessage.add_member(:target_snapshot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetSnapshotName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A name for the snapshot copy. ElastiCache does not permit overwriting a snapshot,\n            therefore this name must be unique within its context - ElastiCache or an Amazon S3\n            bucket if exporting.</p>", "smithy.api#required" => {}}))
    CopySnapshotMessage.add_member(:target_bucket, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetBucket', traits: {"smithy.api#documentation" => "<p>The Amazon S3 bucket to which the snapshot is exported. This parameter is used only\n            when exporting a snapshot for external access.</p>\n         <p>When using this parameter to export a snapshot, be sure Amazon ElastiCache has the\n            needed permissions to this S3 bucket. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/backups-exporting.html#backups-exporting-grant-access\">Step 2: Grant ElastiCache Access to Your Amazon S3 Bucket</a> in the\n                <i>Amazon ElastiCache User Guide</i>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/backups-exporting.html\">Exporting a\n                Snapshot</a> in the <i>Amazon ElastiCache User Guide</i>.</p>"}))
    CopySnapshotMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The ID of the KMS key used to encrypt the target snapshot.</p>"}))
    CopySnapshotMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags to be added to this resource. A tag is a key-value pair. A tag key must\n            be accompanied by a tag value, although null is accepted.</p>"}))
