    CreateCacheClusterMessage.add_member(:cache_cluster_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheClusterId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The node group (shard) identifier. This parameter is stored as a lowercase\n            string.</p>\n         <p>\n            <b>Constraints:</b>\n         </p>\n         <ul>\n            <li>\n               <p>A name must contain from 1 to 50 alphanumeric characters or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>A name cannot end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateCacheClusterMessage.add_member(:replication_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationGroupId', traits: {"smithy.api#documentation" => "<p>The ID of the replication group to which this cluster should belong. If this parameter\n            is specified, the cluster is added to the specified replication group as a read replica;\n            otherwise, the cluster is a standalone primary that is not part of any replication\n            group.</p>\n         <p>If the specified replication group is Multi-AZ enabled and the Availability Zone is\n            not specified, the cluster is created in Availability Zones that provide the best spread\n            of read replicas across Availability Zones.</p>\n         <note>\n            <p>This parameter is only valid if the <code>Engine</code> parameter is\n                    <code>redis</code>.</p>\n         </note>"}))
    CreateCacheClusterMessage.add_member(:az_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AZMode, location_name: 'AZMode', traits: {"smithy.api#documentation" => "<p>Specifies whether the nodes in this Memcached cluster are created in a single\n            Availability Zone or created across multiple Availability Zones in the cluster's\n            region.</p>\n         <p>This parameter is only supported for Memcached clusters.</p>\n         <p>If the <code>AZMode</code> and <code>PreferredAvailabilityZones</code> are not\n            specified, ElastiCache assumes <code>single-az</code> mode.</p>"}))
    CreateCacheClusterMessage.add_member(:preferred_availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredAvailabilityZone', traits: {"smithy.api#documentation" => "<p>The EC2 Availability Zone in which the cluster is created.</p>\n         <p>All nodes belonging to this cluster are placed in the preferred Availability Zone. If\n            you want to create your nodes across multiple Availability Zones, use\n                <code>PreferredAvailabilityZones</code>.</p>\n         <p>Default: System chosen Availability Zone.</p>"}))
    CreateCacheClusterMessage.add_member(:preferred_availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: PreferredAvailabilityZoneList, location_name: 'PreferredAvailabilityZones', traits: {"smithy.api#documentation" => "<p>A list of the Availability Zones in which cache nodes are created. The order of the\n            zones in the list is not important.</p>\n         <p>This option is only supported on Memcached.</p>\n         <note>\n            <p>If you are creating your cluster in an Amazon VPC (recommended) you can only\n                locate nodes in Availability Zones that are associated with the subnets in the\n                selected subnet group.</p>\n            <p>The number of Availability Zones listed must equal the value of\n                    <code>NumCacheNodes</code>.</p>\n         </note>\n         <p>If you want all the nodes in the same Availability Zone, use\n                <code>PreferredAvailabilityZone</code> instead, or repeat the Availability Zone\n            multiple times in the list.</p>\n         <p>Default: System chosen Availability Zones.</p>"}))
    CreateCacheClusterMessage.add_member(:num_cache_nodes, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'NumCacheNodes', traits: {"smithy.api#documentation" => "<p>The initial number of cache nodes that the cluster has.</p>\n         <p>For clusters running Valkey or Redis OSS, this value must be 1. For clusters running Memcached, this\n            value must be between 1 and 40.</p>\n         <p>If you need more than 40 nodes for your Memcached cluster, please fill out the\n            ElastiCache Limit Increase Request form at <a href=\"http://aws.amazon.com/contact-us/elasticache-node-limit-request/\">http://aws.amazon.com/contact-us/elasticache-node-limit-request/</a>.</p>"}))
    CreateCacheClusterMessage.add_member(:cache_node_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheNodeType', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the nodes in the node group (shard).</p>\n         <p>The following node types are supported by ElastiCache. Generally speaking, the current\n            generation types provide more memory and computational power at lower cost when compared\n            to their equivalent previous generation counterparts.</p>\n         <ul>\n            <li>\n               <p>General purpose:</p>\n               <ul>\n                  <li>\n                     <p>Current generation: </p>\n                     <p>\n                        <b>M7g node types</b>:\n    \t\t\t\t\t<code>cache.m7g.large</code>,\n    \t\t\t\t\t<code>cache.m7g.xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.2xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.4xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.8xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.12xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.16xlarge</code>\n                     </p>\n                     <note>\n                        <p>For region availability, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/CacheNodes.SupportedTypes.html#CacheNodes.SupportedTypesByRegion\">Supported Node Types</a>\n                        </p>\n                     </note>\n                     <p>\n                        <b>M6g node types</b> (available only for Redis OSS engine version 5.0.6 onward and for Memcached engine version 1.5.16 onward):\n\t\t\t\t\t    \n\t\t\t\t\t \t<code>cache.m6g.large</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.2xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.4xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.8xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.12xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.16xlarge</code>\n                     </p>\n                     <p>\n                        <b>M5 node types:</b>\n                        <code>cache.m5.large</code>,\n    \t\t\t\t\t\t<code>cache.m5.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.2xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.4xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.12xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.24xlarge</code>\n                     </p>\n                     <p>\n                        <b>M4 node types:</b>\n                        <code>cache.m4.large</code>,\n    \t\t\t\t\t\t<code>cache.m4.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m4.2xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m4.4xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m4.10xlarge</code>\n                     </p>\n                     <p>\n                        <b>T4g node types</b> (available only for Redis OSS engine version 5.0.6 onward and Memcached engine version 1.5.16 onward):\n\t\t\t\t\t        <code>cache.t4g.micro</code>,\n\t\t\t\t\t        <code>cache.t4g.small</code>,\n\t\t\t\t\t        <code>cache.t4g.medium</code>\n                     </p>\n                     <p>\n                        <b>T3 node types:</b>\n                        <code>cache.t3.micro</code>, \n    \t\t\t\t\t\t<code>cache.t3.small</code>,\n    \t\t\t\t\t\t<code>cache.t3.medium</code>\n                     </p>\n                     <p>\n                        <b>T2 node types:</b>\n                        <code>cache.t2.micro</code>, \n    \t\t\t\t\t\t<code>cache.t2.small</code>,\n    \t\t\t\t\t\t<code>cache.t2.medium</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>Previous generation: (not recommended. Existing clusters are still supported but creation of new clusters is not supported for these types.)</p>\n                     <p>\n                        <b>T1 node types:</b>\n                        <code>cache.t1.micro</code>\n                     </p>\n                     <p>\n                        <b>M1 node types:</b>\n                        <code>cache.m1.small</code>, \n\t\t\t\t\t\t   <code>cache.m1.medium</code>, \n\t\t\t\t\t\t   <code>cache.m1.large</code>,\n\t\t\t\t\t\t   <code>cache.m1.xlarge</code>\n                     </p>\n                     <p>\n                        <b>M3 node types:</b>\n                        <code>cache.m3.medium</code>,\n    \t\t\t\t\t\t<code>cache.m3.large</code>, \n    \t\t\t\t\t\t<code>cache.m3.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m3.2xlarge</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>Compute optimized:</p>\n               <ul>\n                  <li>\n                     <p>Previous generation: (not recommended. Existing clusters are still supported but creation of new clusters is not supported for these types.)</p>\n                     <p>\n                        <b>C1 node types:</b>\n                        <code>cache.c1.xlarge</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>Memory optimized:</p>\n               <ul>\n                  <li>\n                     <p>Current generation: </p>\n                     <p>\n                        <b>R7g node types</b>:\t\n\t\t\t\t\t\t\t<code>cache.r7g.large</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.2xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.4xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.8xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.12xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.16xlarge</code>\n                     </p>\n                     <note>\n                        <p>For region availability, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/CacheNodes.SupportedTypes.html#CacheNodes.SupportedTypesByRegion\">Supported Node Types</a>\n                        </p>\n                     </note>\n                     <p>\n                        <b>R6g node types</b> (available only for Redis OSS engine version 5.0.6 onward and for Memcached engine version 1.5.16 onward):\n\t\t\t\t\t\t\t<code>cache.r6g.large</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.2xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.4xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.8xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.12xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.16xlarge</code>\n                     </p>\n                     <p>\n                        <b>R5 node types:</b>\n                        <code>cache.r5.large</code>,\n    \t\t\t\t\t   <code>cache.r5.xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.2xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.4xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.12xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.24xlarge</code>\n                     </p>\n                     <p>\n                        <b>R4 node types:</b>\n                        <code>cache.r4.large</code>,\n    \t\t\t\t\t   <code>cache.r4.xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.2xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.4xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.8xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.16xlarge</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>Previous generation: (not recommended. Existing clusters are still supported but creation of new clusters is not supported for these types.)</p>\n                     <p>\n                        <b>M2 node types:</b>\n                        <code>cache.m2.xlarge</code>, \n    \t\t\t\t\t\t<code>cache.m2.2xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m2.4xlarge</code>\n                     </p>\n                     <p>\n                        <b>R3 node types:</b>\n                        <code>cache.r3.large</code>, \n    \t\t\t\t\t\t<code>cache.r3.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.r3.2xlarge</code>,  \n    \t\t\t\t\t\t<code>cache.r3.4xlarge</code>,\n    \t\t\t\t\t\t<code>cache.r3.8xlarge</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n         </ul>\n         <p>\n            <b>Additional node type info</b>\n         </p>\n         <ul>\n            <li>\n               <p>All current generation instance types are created in Amazon VPC by\n                    default.</p>\n            </li>\n            <li>\n               <p>Valkey or Redis OSS append-only files (AOF) are not supported for T1 or T2 instances.</p>\n            </li>\n            <li>\n               <p>Valkey or Redis OSS Multi-AZ with automatic failover is not supported on T1\n                    instances.</p>\n            </li>\n            <li>\n               <p>The configuration variables <code>appendonly</code> and\n                        <code>appendfsync</code> are not supported on Valkey, or on Redis OSS version 2.8.22 and\n                    later.</p>\n            </li>\n         </ul>"}))
    CreateCacheClusterMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The name of the cache engine to be used for this cluster.</p>\n         <p>Valid values for this parameter are: <code>memcached</code> |\n            <code>redis</code>\n         </p>"}))
    CreateCacheClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the cache engine to be used for this cluster. To view the\n            supported cache engine versions, use the DescribeCacheEngineVersions operation.</p>\n         <p>\n            <b>Important:</b> You can upgrade to a newer engine version\n            (see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/SelectEngine.html#VersionManagement\">Selecting\n                a Cache Engine and Version</a>), but you cannot downgrade to an earlier engine\n            version. If you want to use an earlier engine version, you must delete the existing\n            cluster or replication group and create it anew with the earlier engine version. </p>"}))
    CreateCacheClusterMessage.add_member(:cache_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the parameter group to associate with this cluster. If this argument is\n            omitted, the default parameter group for the specified engine is used. You cannot use\n            any parameter group which has <code>cluster-enabled='yes'</code> when creating a\n            cluster.</p>"}))
    CreateCacheClusterMessage.add_member(:cache_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The name of the subnet group to be used for the cluster.</p>\n         <p>Use this parameter only when you are creating a cluster in an Amazon Virtual Private\n            Cloud (Amazon VPC).</p>\n         <important>\n            <p>If you're going to launch your cluster in an Amazon VPC, you need to create a\n                subnet group before you start creating a cluster. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/SubnetGroups.html\">Subnets and Subnet Groups</a>.</p>\n         </important>"}))
    CreateCacheClusterMessage.add_member(:cache_security_group_names, Smithy::Schema::Shapes::ShapeRef.new(shape: CacheSecurityGroupNameList, location_name: 'CacheSecurityGroupNames', traits: {"smithy.api#documentation" => "<p>A list of security group names to associate with this cluster.</p>\n         <p>Use this parameter only when you are creating a cluster outside of an Amazon Virtual\n            Private Cloud (Amazon VPC).</p>"}))
    CreateCacheClusterMessage.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdsList, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>One or more VPC security groups associated with the cluster.</p>\n         <p>Use this parameter only when you are creating a cluster in an Amazon Virtual Private\n            Cloud (Amazon VPC).</p>"}))
    CreateCacheClusterMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags to be added to this resource.</p>"}))
    CreateCacheClusterMessage.add_member(:snapshot_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotArnsList, location_name: 'SnapshotArns', traits: {"smithy.api#documentation" => "<p>A single-element string list containing an Amazon Resource Name (ARN) that uniquely\n            identifies a Valkey or Redis OSS RDB snapshot file stored in Amazon S3. The snapshot file is used to\n            populate the node group (shard). The Amazon S3 object name in the ARN cannot contain any\n            commas.</p>\n         <note>\n            <p>This parameter is only valid if the <code>Engine</code> parameter is\n                    <code>redis</code>.</p>\n         </note>\n         <p>Example of an Amazon S3 ARN: <code>arn:aws:s3:::my_bucket/snapshot1.rdb</code>\n         </p>"}))
    CreateCacheClusterMessage.add_member(:snapshot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotName', traits: {"smithy.api#documentation" => "<p>The name of a Valkey or Redis OSS snapshot from which to restore data into the new node group\n            (shard). The snapshot status changes to <code>restoring</code> while the new node group\n            (shard) is being created.</p>\n         <note>\n            <p>This parameter is only valid if the <code>Engine</code> parameter is\n                    <code>redis</code>.</p>\n         </note>"}))
    CreateCacheClusterMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>Specifies the weekly time range during which maintenance on the cluster is performed.\n            It is specified as a range in the format ddd:hh24:mi-ddd:hh24:mi (24H Clock UTC). The\n            minimum maintenance window is a 60 minute period. </p>"}))
    CreateCacheClusterMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which each of the cache nodes accepts connections.</p>"}))
    CreateCacheClusterMessage.add_member(:notification_topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NotificationTopicArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon Simple Notification Service (SNS) topic\n            to which notifications are sent.</p>\n         <note>\n            <p>The Amazon SNS topic owner must be the same as the cluster owner.</p>\n         </note>"}))
    CreateCacheClusterMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p> If you are running Valkey 7.2 and above or Redis OSS engine version 6.0 and above, set this parameter to yes \n            to opt-in to the next auto minor version upgrade campaign. This parameter is\n            disabled for previous versions.  </p>"}))
    CreateCacheClusterMessage.add_member(:snapshot_retention_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SnapshotRetentionLimit', traits: {"smithy.api#documentation" => "<p>The number of days for which ElastiCache retains automatic snapshots before deleting\n            them. For example, if you set <code>SnapshotRetentionLimit</code> to 5, a snapshot taken\n            today is retained for 5 days before being deleted.</p>\n         <note>\n            <p>This parameter is only valid if the <code>Engine</code> parameter is\n                    <code>redis</code>.</p>\n         </note>\n         <p>Default: 0 (i.e., automatic backups are disabled for this cache cluster).</p>"}))
    CreateCacheClusterMessage.add_member(:snapshot_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotWindow', traits: {"smithy.api#documentation" => "<p>The daily time range (in UTC) during which ElastiCache begins taking a daily snapshot\n            of your node group (shard).</p>\n         <p>Example: <code>05:00-09:00</code>\n         </p>\n         <p>If you do not specify this parameter, ElastiCache automatically chooses an appropriate\n            time range.</p>\n         <note>\n            <p>This parameter is only valid if the <code>Engine</code> parameter is\n                    <code>redis</code>.</p>\n         </note>"}))
    CreateCacheClusterMessage.add_member(:auth_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AuthToken', traits: {"smithy.api#documentation" => "<p>\n            <b>Reserved parameter.</b> The password used to access a\n            password protected server.</p>\n         <p>Password constraints:</p>\n         <ul>\n            <li>\n               <p>Must be only printable ASCII characters.</p>\n            </li>\n            <li>\n               <p>Must be at least 16 characters and no more than 128 characters in\n                    length.</p>\n            </li>\n            <li>\n               <p>The only permitted printable special characters are !, &, #, $, ^, <,\n                    >, and -. Other printable special characters cannot be used in the AUTH\n                    token.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"http://redis.io/commands/AUTH\">AUTH\n                password</a> at http://redis.io/commands/AUTH.</p>"}))
    CreateCacheClusterMessage.add_member(:outpost_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: OutpostMode, location_name: 'OutpostMode', traits: {"smithy.api#documentation" => "<p>Specifies whether the nodes in the cluster are created in a single outpost or across\n            multiple outposts.</p>"}))
    CreateCacheClusterMessage.add_member(:preferred_outpost_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredOutpostArn', traits: {"smithy.api#documentation" => "<p>The outpost ARN in which the cache cluster is created.</p>"}))
    CreateCacheClusterMessage.add_member(:preferred_outpost_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: PreferredOutpostArnList, location_name: 'PreferredOutpostArns', traits: {"smithy.api#documentation" => "<p>The outpost ARNs in which the cache cluster is created.</p>"}))
    CreateCacheClusterMessage.add_member(:log_delivery_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: LogDeliveryConfigurationRequestList, location_name: 'LogDeliveryConfigurations', traits: {"smithy.api#documentation" => "<p>Specifies the destination, format and type of the logs. </p>"}))
    CreateCacheClusterMessage.add_member(:transit_encryption_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TransitEncryptionEnabled', traits: {"smithy.api#documentation" => "<p>A flag that enables in-transit encryption when set to true.</p>"}))
    CreateCacheClusterMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkType, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>Must be either <code>ipv4</code> | <code>ipv6</code> | <code>dual_stack</code>. IPv6\n            is supported for workloads using Valkey 7.2 and above, Redis OSS engine version 6.2 to 7.1\n            and Memcached engine version 1.6.6 and above on all instances built on the <a href=\"http://aws.amazon.com/ec2/nitro/\">Nitro system</a>. </p>"}))
    CreateCacheClusterMessage.add_member(:ip_discovery, Smithy::Schema::Shapes::ShapeRef.new(shape: IpDiscovery, location_name: 'IpDiscovery', traits: {"smithy.api#documentation" => "<p>The network type you choose when modifying a cluster, either <code>ipv4</code> |\n            <code>ipv6</code>. IPv6 is supported for workloads using Valkey 7.2 and above, Redis OSS engine version 6.2\n            to 7.1 and Memcached engine version 1.6.6 and above on all instances built on the <a href=\"http://aws.amazon.com/ec2/nitro/\">Nitro system</a>.</p>"}))
    CreateCacheClusterMessage.type = Types::CreateCacheClusterMessage
    CreateCacheClusterResult.add_member(:cache_cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: CacheCluster, location_name: 'CacheCluster'))
    CreateCacheClusterResult.type = Types::CreateCacheClusterResult
    CreateCacheParameterGroupMessage.add_member(:cache_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheParameterGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A user-specified name for the cache parameter group.</p>", "smithy.api#required" => {}}))
    CreateCacheParameterGroupMessage.add_member(:cache_parameter_group_family, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheParameterGroupFamily', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the cache parameter group family that the cache parameter group can be\n            used with.</p>\n         <p>Valid values are: <code>valkey8</code> | <code>valkey7</code> | <code>memcached1.4</code> | <code>memcached1.5</code> | <code>memcached1.6</code> | <code>redis2.6</code> | <code>redis2.8</code> |\n<code>redis3.2</code> | <code>redis4.0</code> | <code>redis5.0</code> | <code>redis6.x</code> | <code>redis7</code>\n         </p>", "smithy.api#required" => {}}))
    CreateCacheParameterGroupMessage.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A user-specified description for the cache parameter group.</p>", "smithy.api#required" => {}}))
    CreateCacheParameterGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags to be added to this resource. A tag is a key-value pair. A tag key must\n            be accompanied by a tag value, although null is accepted.</p>"}))
    CreateCacheParameterGroupMessage.type = Types::CreateCacheParameterGroupMessage
