    CreateCacheSecurityGroupMessage.add_member(:cache_security_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheSecurityGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A name for the cache security group. This value is stored as a lowercase\n            string.</p>\n         <p>Constraints: Must contain no more than 255 alphanumeric characters. Cannot be the word\n            \"Default\".</p>\n         <p>Example: <code>mysecuritygroup</code>\n         </p>", "smithy.api#required" => {}}))
    CreateCacheSecurityGroupMessage.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description for the cache security group.</p>", "smithy.api#required" => {}}))
    CreateCacheSecurityGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags to be added to this resource. A tag is a key-value pair. A tag key must\n            be accompanied by a tag value, although null is accepted.</p>"}))
    CreateCacheSecurityGroupMessage.type = Types::CreateCacheSecurityGroupMessage
    CreateCacheSecurityGroupResult.add_member(:cache_security_group, Smithy::Schema::Shapes::ShapeRef.new(shape: CacheSecurityGroup, location_name: 'CacheSecurityGroup'))
    CreateCacheSecurityGroupResult.type = Types::CreateCacheSecurityGroupResult
    CreateCacheSubnetGroupMessage.add_member(:cache_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheSubnetGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A name for the cache subnet group. This value is stored as a lowercase string.</p>\n         <p>Constraints: Must contain no more than 255 alphanumeric characters or hyphens.</p>\n         <p>Example: <code>mysubnetgroup</code>\n         </p>", "smithy.api#required" => {}}))
    CreateCacheSubnetGroupMessage.add_member(:cache_subnet_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheSubnetGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description for the cache subnet group.</p>", "smithy.api#required" => {}}))
    CreateCacheSubnetGroupMessage.add_member(:subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetIdentifierList, location_name: 'SubnetIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of VPC subnet IDs for the cache subnet group.</p>", "smithy.api#required" => {}}))
    CreateCacheSubnetGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags to be added to this resource. A tag is a key-value pair. A tag key must\n            be accompanied by a tag value, although null is accepted.</p>"}))
    CreateCacheSubnetGroupMessage.type = Types::CreateCacheSubnetGroupMessage
    CreateCacheSubnetGroupResult.add_member(:cache_subnet_group, Smithy::Schema::Shapes::ShapeRef.new(shape: CacheSubnetGroup, location_name: 'CacheSubnetGroup'))
    CreateCacheSubnetGroupResult.type = Types::CreateCacheSubnetGroupResult
    CreateGlobalReplicationGroupMessage.add_member(:global_replication_group_id_suffix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'GlobalReplicationGroupIdSuffix', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The suffix name of a Global datastore. Amazon ElastiCache automatically applies a\n            prefix to the Global datastore ID when it is created. Each Amazon Region has its own\n            prefix. For instance, a Global datastore ID created in the US-West-1 region will begin\n            with \"dsdfu\" along with the suffix name you provide. The suffix, combined with the\n            auto-generated prefix, guarantees uniqueness of the Global datastore name across\n            multiple regions. </p>\n         <p>For a full list of Amazon Regions and their respective Global datastore iD prefixes,\n            see <a href=\"http://docs.aws.amazon.com/AmazonElastiCache/latest/dg/Redis-Global-Datastores-CLI.html\">Using the Amazon CLI with Global datastores </a>.</p>", "smithy.api#required" => {}}))
    CreateGlobalReplicationGroupMessage.add_member(:global_replication_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'GlobalReplicationGroupDescription', traits: {"smithy.api#documentation" => "<p>Provides details of the Global datastore</p>"}))
    CreateGlobalReplicationGroupMessage.add_member(:primary_replication_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrimaryReplicationGroupId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the primary cluster that accepts writes and will replicate updates to the\n            secondary cluster.</p>", "smithy.api#required" => {}}))
    CreateGlobalReplicationGroupMessage.type = Types::CreateGlobalReplicationGroupMessage
    CreateGlobalReplicationGroupResult.add_member(:global_replication_group, Smithy::Schema::Shapes::ShapeRef.new(shape: GlobalReplicationGroup, location_name: 'GlobalReplicationGroup'))
    CreateGlobalReplicationGroupResult.type = Types::CreateGlobalReplicationGroupResult
    CreateReplicationGroupMessage.add_member(:replication_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationGroupId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The replication group identifier. This parameter is stored as a lowercase\n            string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>A name must contain from 1 to 40 alphanumeric characters or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>A name cannot end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateReplicationGroupMessage.add_member(:replication_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A user-created description for the replication group.</p>", "smithy.api#required" => {}}))
    CreateReplicationGroupMessage.add_member(:global_replication_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'GlobalReplicationGroupId', traits: {"smithy.api#documentation" => "<p>The name of the Global datastore</p>"}))
    CreateReplicationGroupMessage.add_member(:primary_cluster_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrimaryClusterId', traits: {"smithy.api#documentation" => "<p>The identifier of the cluster that serves as the primary for this replication group.\n            This cluster must already exist and have a status of <code>available</code>.</p>\n         <p>This parameter is not required if <code>NumCacheClusters</code>,\n                <code>NumNodeGroups</code>, or <code>ReplicasPerNodeGroup</code> is\n            specified.</p>"}))
    CreateReplicationGroupMessage.add_member(:automatic_failover_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutomaticFailoverEnabled', traits: {"smithy.api#documentation" => "<p>Specifies whether a read-only replica is automatically promoted to read/write primary\n            if the existing primary fails.</p>\n         <p>\n            <code>AutomaticFailoverEnabled</code> must be enabled for Valkey or Redis OSS (cluster mode enabled)\n            replication groups.</p>\n         <p>Default: false</p>"}))
    CreateReplicationGroupMessage.add_member(:multi_az_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZEnabled', traits: {"smithy.api#documentation" => "<p>A flag indicating if you have Multi-AZ enabled to enhance fault tolerance. For more\n            information, see <a href=\"http://docs.aws.amazon.com/AmazonElastiCache/latest/dg/AutoFailover.html\">Minimizing Downtime: Multi-AZ</a>.</p>"}))
    CreateReplicationGroupMessage.add_member(:num_cache_clusters, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'NumCacheClusters', traits: {"smithy.api#documentation" => "<p>The number of clusters this replication group initially has.</p>\n         <p>This parameter is not used if there is more than one node group (shard). You should\n            use <code>ReplicasPerNodeGroup</code> instead.</p>\n         <p>If <code>AutomaticFailoverEnabled</code> is <code>true</code>, the value of this\n            parameter must be at least 2. If <code>AutomaticFailoverEnabled</code> is\n                <code>false</code> you can omit this parameter (it will default to 1), or you can\n            explicitly set it to a value between 2 and 6.</p>\n         <p>The maximum permitted value for <code>NumCacheClusters</code> is 6 (1 primary plus 5\n            replicas).</p>"}))
    CreateReplicationGroupMessage.add_member(:preferred_cache_cluster_a_zs, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZonesList, location_name: 'PreferredCacheClusterAZs', traits: {"smithy.api#documentation" => "<p>A list of EC2 Availability Zones in which the replication group's clusters are\n            created. The order of the Availability Zones in the list is the order in which clusters\n            are allocated. The primary cluster is created in the first AZ in the list.</p>\n         <p>This parameter is not used if there is more than one node group (shard). You should\n            use <code>NodeGroupConfiguration</code> instead.</p>\n         <note>\n            <p>If you are creating your replication group in an Amazon VPC (recommended), you can\n                only locate clusters in Availability Zones associated with the subnets in the\n                selected subnet group.</p>\n            <p>The number of Availability Zones listed must equal the value of\n                    <code>NumCacheClusters</code>.</p>\n         </note>\n         <p>Default: system chosen Availability Zones.</p>"}))
    CreateReplicationGroupMessage.add_member(:num_node_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'NumNodeGroups', traits: {"smithy.api#documentation" => "<p>An optional parameter that specifies the number of node groups (shards) for this Valkey or Redis OSS (cluster mode enabled) replication group. For Valkey or Redis OSS (cluster mode disabled) either omit\n            this parameter or set it to 1.</p>\n         <p>Default: 1</p>"}))
    CreateReplicationGroupMessage.add_member(:replicas_per_node_group, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ReplicasPerNodeGroup', traits: {"smithy.api#documentation" => "<p>An optional parameter that specifies the number of replica nodes in each node group\n            (shard). Valid values are 0 to 5.</p>"}))
    CreateReplicationGroupMessage.add_member(:node_group_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NodeGroupConfigurationList, location_name: 'NodeGroupConfiguration', traits: {"smithy.api#documentation" => "<p>A list of node group (shard) configuration options. Each node group (shard)\n            configuration has the following members: <code>PrimaryAvailabilityZone</code>,\n                <code>ReplicaAvailabilityZones</code>, <code>ReplicaCount</code>, and\n                <code>Slots</code>.</p>\n         <p>If you're creating a Valkey or Redis OSS (cluster mode disabled) or a Valkey or Redis OSS (cluster mode enabled)\n            replication group, you can use this parameter to individually configure each node group\n            (shard), or you can omit this parameter. However, it is required when seeding a Valkey or Redis OSS (cluster mode enabled) cluster from a S3 rdb file. You must configure each node group\n            (shard) using this parameter because you must specify the slots for each node\n            group.</p>"}))
    CreateReplicationGroupMessage.add_member(:cache_node_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheNodeType', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the nodes in the node group (shard).</p>\n         <p>The following node types are supported by ElastiCache. Generally speaking, the current\n            generation types provide more memory and computational power at lower cost when compared\n            to their equivalent previous generation counterparts.</p>\n         <ul>\n            <li>\n               <p>General purpose:</p>\n               <ul>\n                  <li>\n                     <p>Current generation: </p>\n                     <p>\n                        <b>M7g node types</b>:\n    \t\t\t\t\t<code>cache.m7g.large</code>,\n    \t\t\t\t\t<code>cache.m7g.xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.2xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.4xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.8xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.12xlarge</code>,\n    \t\t\t\t\t<code>cache.m7g.16xlarge</code>\n                     </p>\n                     <note>\n                        <p>For region availability, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/CacheNodes.SupportedTypes.html#CacheNodes.SupportedTypesByRegion\">Supported Node Types</a>\n                        </p>\n                     </note>\n                     <p>\n                        <b>M6g node types</b> (available only for Redis OSS engine version 5.0.6 onward and for Memcached engine version 1.5.16 onward):\n\t\t\t\t\t    \n\t\t\t\t\t \t<code>cache.m6g.large</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.2xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.4xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.8xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.12xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.m6g.16xlarge</code>\n                     </p>\n                     <p>\n                        <b>M5 node types:</b>\n                        <code>cache.m5.large</code>,\n    \t\t\t\t\t\t<code>cache.m5.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.2xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.4xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.12xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m5.24xlarge</code>\n                     </p>\n                     <p>\n                        <b>M4 node types:</b>\n                        <code>cache.m4.large</code>,\n    \t\t\t\t\t\t<code>cache.m4.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m4.2xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m4.4xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m4.10xlarge</code>\n                     </p>\n                     <p>\n                        <b>T4g node types</b> (available only for Redis OSS engine version 5.0.6 onward and Memcached engine version 1.5.16 onward):\n\t\t\t\t\t        <code>cache.t4g.micro</code>,\n\t\t\t\t\t        <code>cache.t4g.small</code>,\n\t\t\t\t\t        <code>cache.t4g.medium</code>\n                     </p>\n                     <p>\n                        <b>T3 node types:</b>\n                        <code>cache.t3.micro</code>, \n    \t\t\t\t\t\t<code>cache.t3.small</code>,\n    \t\t\t\t\t\t<code>cache.t3.medium</code>\n                     </p>\n                     <p>\n                        <b>T2 node types:</b>\n                        <code>cache.t2.micro</code>, \n    \t\t\t\t\t\t<code>cache.t2.small</code>,\n    \t\t\t\t\t\t<code>cache.t2.medium</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>Previous generation: (not recommended. Existing clusters are still supported but creation of new clusters is not supported for these types.)</p>\n                     <p>\n                        <b>T1 node types:</b>\n                        <code>cache.t1.micro</code>\n                     </p>\n                     <p>\n                        <b>M1 node types:</b>\n                        <code>cache.m1.small</code>, \n\t\t\t\t\t\t   <code>cache.m1.medium</code>, \n\t\t\t\t\t\t   <code>cache.m1.large</code>,\n\t\t\t\t\t\t   <code>cache.m1.xlarge</code>\n                     </p>\n                     <p>\n                        <b>M3 node types:</b>\n                        <code>cache.m3.medium</code>,\n    \t\t\t\t\t\t<code>cache.m3.large</code>, \n    \t\t\t\t\t\t<code>cache.m3.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m3.2xlarge</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>Compute optimized:</p>\n               <ul>\n                  <li>\n                     <p>Previous generation: (not recommended. Existing clusters are still supported but creation of new clusters is not supported for these types.)</p>\n                     <p>\n                        <b>C1 node types:</b>\n                        <code>cache.c1.xlarge</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>Memory optimized:</p>\n               <ul>\n                  <li>\n                     <p>Current generation: </p>\n                     <p>\n                        <b>R7g node types</b>:\t\n\t\t\t\t\t\t\t<code>cache.r7g.large</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.2xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.4xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.8xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.12xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r7g.16xlarge</code>\n                     </p>\n                     <note>\n                        <p>For region availability, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/CacheNodes.SupportedTypes.html#CacheNodes.SupportedTypesByRegion\">Supported Node Types</a>\n                        </p>\n                     </note>\n                     <p>\n                        <b>R6g node types</b> (available only for Redis OSS engine version 5.0.6 onward and for Memcached engine version 1.5.16 onward):\n\t\t\t\t\t\t\t<code>cache.r6g.large</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.2xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.4xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.8xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.12xlarge</code>,\n\t\t\t\t\t\t\t<code>cache.r6g.16xlarge</code>\n                     </p>\n                     <p>\n                        <b>R5 node types:</b>\n                        <code>cache.r5.large</code>,\n    \t\t\t\t\t   <code>cache.r5.xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.2xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.4xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.12xlarge</code>,\n    \t\t\t\t\t   <code>cache.r5.24xlarge</code>\n                     </p>\n                     <p>\n                        <b>R4 node types:</b>\n                        <code>cache.r4.large</code>,\n    \t\t\t\t\t   <code>cache.r4.xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.2xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.4xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.8xlarge</code>,\n    \t\t\t\t\t   <code>cache.r4.16xlarge</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>Previous generation: (not recommended. Existing clusters are still supported but creation of new clusters is not supported for these types.)</p>\n                     <p>\n                        <b>M2 node types:</b>\n                        <code>cache.m2.xlarge</code>, \n    \t\t\t\t\t\t<code>cache.m2.2xlarge</code>,\n    \t\t\t\t\t\t<code>cache.m2.4xlarge</code>\n                     </p>\n                     <p>\n                        <b>R3 node types:</b>\n                        <code>cache.r3.large</code>, \n    \t\t\t\t\t\t<code>cache.r3.xlarge</code>,\n    \t\t\t\t\t\t<code>cache.r3.2xlarge</code>,  \n    \t\t\t\t\t\t<code>cache.r3.4xlarge</code>,\n    \t\t\t\t\t\t<code>cache.r3.8xlarge</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n         </ul>\n         <p>\n            <b>Additional node type info</b>\n         </p>\n         <ul>\n            <li>\n               <p>All current generation instance types are created in Amazon VPC by\n                    default.</p>\n            </li>\n            <li>\n               <p>Valkey or Redis OSS append-only files (AOF) are not supported for T1 or T2 instances.</p>\n            </li>\n            <li>\n               <p>Valkey or Redis OSS Multi-AZ with automatic failover is not supported on T1\n                    instances.</p>\n            </li>\n            <li>\n               <p>The configuration variables <code>appendonly</code> and\n                        <code>appendfsync</code> are not supported on Valkey, or on Redis OSS version 2.8.22 and\n                    later.</p>\n            </li>\n         </ul>"}))
    CreateReplicationGroupMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The name of the cache engine to be used for the clusters in this replication group.\n            The value must be set to <code>valkey</code> or <code>redis</code>.</p>"}))
    CreateReplicationGroupMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the cache engine to be used for the clusters in this replication\n            group. To view the supported cache engine versions, use the\n                <code>DescribeCacheEngineVersions</code> operation.</p>\n         <p>\n            <b>Important:</b> You can upgrade to a newer engine version\n            (see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/SelectEngine.html#VersionManagement\">Selecting\n                a Cache Engine and Version</a>) in the <i>ElastiCache User\n                Guide</i>, but you cannot downgrade to an earlier engine version. If you want\n            to use an earlier engine version, you must delete the existing cluster or replication\n            group and create it anew with the earlier engine version. </p>"}))
    CreateReplicationGroupMessage.add_member(:cache_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the parameter group to associate with this replication group. If this\n            argument is omitted, the default cache parameter group for the specified engine is\n            used.</p>\n         <p>If you are running Valkey or Redis OSS version 3.2.4 or later, only one node group (shard), and want\n            to use a default parameter group, we recommend that you specify the parameter group by\n            name. </p>\n         <ul>\n            <li>\n               <p>To create a Valkey or Redis OSS (cluster mode disabled) replication group, use\n                        <code>CacheParameterGroupName=default.redis3.2</code>.</p>\n            </li>\n            <li>\n               <p>To create a Valkey or Redis OSS (cluster mode enabled) replication group, use\n                        <code>CacheParameterGroupName=default.redis3.2.cluster.on</code>.</p>\n            </li>\n         </ul>"}))
    CreateReplicationGroupMessage.add_member(:cache_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The name of the cache subnet group to be used for the replication group.</p>\n         <important>\n            <p>If you're going to launch your cluster in an Amazon VPC, you need to create a\n                subnet group before you start creating a cluster. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/SubnetGroups.html\">Subnets and Subnet Groups</a>.</p>\n         </important>"}))
    CreateReplicationGroupMessage.add_member(:cache_security_group_names, Smithy::Schema::Shapes::ShapeRef.new(shape: CacheSecurityGroupNameList, location_name: 'CacheSecurityGroupNames', traits: {"smithy.api#documentation" => "<p>A list of cache security group names to associate with this replication group.</p>"}))
    CreateReplicationGroupMessage.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdsList, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>One or more Amazon VPC security groups associated with this replication group.</p>\n         <p>Use this parameter only when you are creating a replication group in an Amazon Virtual\n            Private Cloud (Amazon VPC).</p>"}))
    CreateReplicationGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags to be added to this resource. Tags are comma-separated key,value pairs\n            (e.g. Key=<code>myKey</code>, Value=<code>myKeyValue</code>. You can include multiple\n            tags as shown following: Key=<code>myKey</code>, Value=<code>myKeyValue</code>\n                Key=<code>mySecondKey</code>, Value=<code>mySecondKeyValue</code>. Tags on\n            replication groups will be replicated to all nodes.</p>"}))
    CreateReplicationGroupMessage.add_member(:snapshot_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotArnsList, location_name: 'SnapshotArns', traits: {"smithy.api#documentation" => "<p>A list of Amazon Resource Names (ARN) that uniquely identify the Valkey or Redis OSS RDB snapshot\n            files stored in Amazon S3. The snapshot files are used to populate the new replication\n            group. The Amazon S3 object name in the ARN cannot contain any commas. The new\n            replication group will have the number of node groups (console: shards) specified by the\n            parameter <i>NumNodeGroups</i> or the number of node groups configured by\n                <i>NodeGroupConfiguration</i> regardless of the number of ARNs\n            specified here.</p>\n         <p>Example of an Amazon S3 ARN: <code>arn:aws:s3:::my_bucket/snapshot1.rdb</code>\n         </p>"}))
    CreateReplicationGroupMessage.add_member(:snapshot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotName', traits: {"smithy.api#documentation" => "<p>The name of a snapshot from which to restore data into the new replication group. The\n            snapshot status changes to <code>restoring</code> while the new replication group is\n            being created.</p>"}))
    CreateReplicationGroupMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>Specifies the weekly time range during which maintenance on the cluster is performed.\n            It is specified as a range in the format ddd:hh24:mi-ddd:hh24:mi (24H Clock UTC). The\n            minimum maintenance window is a 60 minute period.</p>\n         <p>Valid values for <code>ddd</code> are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>sun</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mon</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>tue</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>wed</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>thu</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>fri</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sat</code>\n               </p>\n            </li>\n         </ul>\n         <p>Example: <code>sun:23:00-mon:01:30</code>\n         </p>"}))
    CreateReplicationGroupMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which each member of the replication group accepts\n            connections.</p>"}))
    CreateReplicationGroupMessage.add_member(:notification_topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NotificationTopicArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon Simple Notification Service (SNS) topic\n            to which notifications are sent.</p>\n         <note>\n            <p>The Amazon SNS topic owner must be the same as the cluster owner.</p>\n         </note>"}))
    CreateReplicationGroupMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p> If you are running Valkey 7.2 and above or Redis OSS engine version 6.0 and above, set this parameter to yes \n            to opt-in to the next auto minor version upgrade campaign. This parameter is\n            disabled for previous versions.  </p>"}))
    CreateReplicationGroupMessage.add_member(:snapshot_retention_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SnapshotRetentionLimit', traits: {"smithy.api#documentation" => "<p>The number of days for which ElastiCache retains automatic snapshots before deleting\n            them. For example, if you set <code>SnapshotRetentionLimit</code> to 5, a snapshot that\n            was taken today is retained for 5 days before being deleted.</p>\n         <p>Default: 0 (i.e., automatic backups are disabled for this cluster).</p>"}))
    CreateReplicationGroupMessage.add_member(:snapshot_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotWindow', traits: {"smithy.api#documentation" => "<p>The daily time range (in UTC) during which ElastiCache begins taking a daily snapshot\n            of your node group (shard).</p>\n         <p>Example: <code>05:00-09:00</code>\n         </p>\n         <p>If you do not specify this parameter, ElastiCache automatically chooses an appropriate\n            time range.</p>"}))
    CreateReplicationGroupMessage.add_member(:auth_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AuthToken', traits: {"smithy.api#documentation" => "<p>\n            <b>Reserved parameter.</b> The password used to access a\n            password protected server.</p>\n         <p>\n            <code>AuthToken</code> can be specified only on replication groups where\n                <code>TransitEncryptionEnabled</code> is <code>true</code>.</p>\n         <important>\n            <p>For HIPAA compliance, you must specify <code>TransitEncryptionEnabled</code> as\n                    <code>true</code>, an <code>AuthToken</code>, and a\n                    <code>CacheSubnetGroup</code>.</p>\n         </important>\n         <p>Password constraints:</p>\n         <ul>\n            <li>\n               <p>Must be only printable ASCII characters.</p>\n            </li>\n            <li>\n               <p>Must be at least 16 characters and no more than 128 characters in\n                    length.</p>\n            </li>\n            <li>\n               <p>The only permitted printable special characters are !, &, #, $, ^, <,\n                    >, and -. Other printable special characters cannot be used in the AUTH\n                    token.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"http://redis.io/commands/AUTH\">AUTH\n                password</a> at http://redis.io/commands/AUTH.</p>"}))
    CreateReplicationGroupMessage.add_member(:transit_encryption_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TransitEncryptionEnabled', traits: {"smithy.api#documentation" => "<p>A flag that enables in-transit encryption when set to <code>true</code>.</p>\n         <p>This parameter is valid only if the <code>Engine</code> parameter is\n                <code>redis</code>, the <code>EngineVersion</code> parameter is <code>3.2.6</code>,\n                <code>4.x</code> or later, and the cluster is being created in an Amazon VPC.</p>\n         <p>If you enable in-transit encryption, you must also specify a value for\n                <code>CacheSubnetGroup</code>.</p>\n         <p>\n            <b>Required:</b> Only available when creating a replication\n            group in an Amazon VPC using Redis OSS version <code>3.2.6</code>, <code>4.x</code> or\n            later.</p>\n         <p>Default: <code>false</code>\n         </p>\n         <important>\n            <p>For HIPAA compliance, you must specify <code>TransitEncryptionEnabled</code> as\n                    <code>true</code>, an <code>AuthToken</code>, and a\n                    <code>CacheSubnetGroup</code>.</p>\n         </important>"}))
    CreateReplicationGroupMessage.add_member(:at_rest_encryption_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AtRestEncryptionEnabled', traits: {"smithy.api#documentation" => "<p>A flag that enables encryption at rest when set to <code>true</code>.</p>\n         <p>You cannot modify the value of <code>AtRestEncryptionEnabled</code> after the\n            replication group is created. To enable encryption at rest on a replication group you\n            must set <code>AtRestEncryptionEnabled</code> to <code>true</code> when you create the\n            replication group. </p>\n         <p>\n            <b>Required:</b> Only available when creating a replication\n            group in an Amazon VPC using Valkey 7.2 and later, Redis OSS version <code>3.2.6</code>, or Redis OSS <code>4.x</code> and\n            later.</p>\n         <p>Default: <code>true</code> when using Valkey, <code>false</code> when using Redis OSS</p>"}))
    CreateReplicationGroupMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The ID of the KMS key used to encrypt the disk in the cluster.</p>"}))
    CreateReplicationGroupMessage.add_member(:user_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: UserGroupIdListInput, location_name: 'UserGroupIds', traits: {"smithy.api#documentation" => "<p>The user group to associate with the replication group.</p>"}))
    CreateReplicationGroupMessage.add_member(:log_delivery_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: LogDeliveryConfigurationRequestList, location_name: 'LogDeliveryConfigurations', traits: {"smithy.api#documentation" => "<p>Specifies the destination, format and type of the logs.</p>"}))
    CreateReplicationGroupMessage.add_member(:data_tiering_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DataTieringEnabled', traits: {"smithy.api#documentation" => "<p>Enables data tiering. Data tiering is only supported for replication groups using the\n            r6gd node type. This parameter must be set to true when using r6gd nodes. For more\n            information, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/data-tiering.html\">Data tiering</a>.</p>"}))
    CreateReplicationGroupMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkType, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>Must be either <code>ipv4</code> | <code>ipv6</code> | <code>dual_stack</code>. IPv6\n            is supported for workloads using Valkey 7.2 and above, Redis OSS engine version 6.2\n            to 7.1 and Memcached engine version 1.6.6 and above on all instances built on the <a href=\"http://aws.amazon.com/ec2/nitro/\">Nitro system</a>.</p>"}))
    CreateReplicationGroupMessage.add_member(:ip_discovery, Smithy::Schema::Shapes::ShapeRef.new(shape: IpDiscovery, location_name: 'IpDiscovery', traits: {"smithy.api#documentation" => "<p>The network type you choose when creating a replication group, either\n            <code>ipv4</code> | <code>ipv6</code>. IPv6 is supported for workloads using Valkey 7.2 and above, Redis OSS engine version 6.2\n            to 7.1 or Memcached engine version 1.6.6 and above on all instances built on\n            the <a href=\"http://aws.amazon.com/ec2/nitro/\">Nitro system</a>.</p>"}))
    CreateReplicationGroupMessage.add_member(:transit_encryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitEncryptionMode, location_name: 'TransitEncryptionMode', traits: {"smithy.api#documentation" => "<p>A setting that allows you to migrate your clients to use in-transit encryption, with\n            no downtime.</p>\n         <p>When setting <code>TransitEncryptionEnabled</code> to <code>true</code>, you can set\n            your <code>TransitEncryptionMode</code> to <code>preferred</code> in the same request,\n            to allow both encrypted and unencrypted connections at the same time. Once you migrate\n            all your Valkey or Redis OSS clients to use encrypted connections you can modify the value to\n                <code>required</code> to allow encrypted connections only.</p>\n         <p>Setting <code>TransitEncryptionMode</code> to <code>required</code> is a two-step\n            process that requires you to first set the <code>TransitEncryptionMode</code> to\n                <code>preferred</code>, after that you can set <code>TransitEncryptionMode</code> to\n                <code>required</code>.</p>\n         <p>This process will not trigger the replacement of the replication group.</p>"}))
    CreateReplicationGroupMessage.add_member(:cluster_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ClusterMode, location_name: 'ClusterMode', traits: {"smithy.api#documentation" => "<p>Enabled or Disabled. To modify cluster mode from Disabled to Enabled, you must first\n            set the cluster mode to Compatible. Compatible mode allows your Valkey or Redis OSS clients to connect\n            using both cluster mode enabled and cluster mode disabled. After you migrate all Valkey or Redis OSS \n            clients to use cluster mode enabled, you can then complete cluster mode configuration\n            and set the cluster mode to Enabled.</p>"}))
    CreateReplicationGroupMessage.add_member(:serverless_cache_snapshot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerlessCacheSnapshotName', traits: {"smithy.api#documentation" => "<p>The name of the snapshot used to create a replication group. Available for Valkey, Redis OSS only.</p>"}))
