    ModifyCacheClusterMessage.add_member(:scale_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ScaleConfig, location_name: 'ScaleConfig', traits: {"smithy.api#documentation" => "<p>Configures horizontal or vertical scaling for Memcached clusters, specifying the scaling percentage and interval.</p>"}))
