    ModifyGlobalReplicationGroupMessage.add_member(:global_replication_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'GlobalReplicationGroupId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Global datastore</p>", "smithy.api#required" => {}}))
