    ModifyGlobalReplicationGroupMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>Modifies the engine listed in a global replication group message. The options are redis, memcached or valkey.</p>"}))
