    ModifyGlobalReplicationGroupMessage.add_member(:cache_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the cache parameter group to use with the Global datastore. It must be\n            compatible with the major engine version used by the Global datastore.</p>"}))
