    ModifyGlobalReplicationGroupMessage.add_member(:automatic_failover_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutomaticFailoverEnabled', traits: {"smithy.api#documentation" => "<p>Determines whether a read replica is automatically promoted to read/write primary if\n            the existing primary encounters a failure. </p>"}))
