    ModifyReplicationGroupMessage.add_member(:replication_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationGroupId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier of the replication group to modify.</p>", "smithy.api#required" => {}}))
    ModifyReplicationGroupMessage.add_member(:replication_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationGroupDescription', traits: {"smithy.api#documentation" => "<p>A description for the replication group. Maximum length is 255 characters.</p>"}))
    ModifyReplicationGroupMessage.add_member(:primary_cluster_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrimaryClusterId', traits: {"smithy.api#documentation" => "<p>For replication groups with a single primary, if this parameter is specified,\n            ElastiCache promotes the specified cluster in the specified replication group to the\n            primary role. The nodes of all other clusters in the replication group are read\n            replicas.</p>"}))
    ModifyReplicationGroupMessage.add_member(:snapshotting_cluster_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshottingClusterId', traits: {"smithy.api#documentation" => "<p>The cluster ID that is used as the daily snapshot source for the replication group.\n            This parameter cannot be set for Valkey or Redis OSS (cluster mode enabled) replication groups.</p>"}))
    ModifyReplicationGroupMessage.add_member(:automatic_failover_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutomaticFailoverEnabled', traits: {"smithy.api#documentation" => "<p>Determines whether a read replica is automatically promoted to read/write primary if\n            the existing primary encounters a failure.</p>\n         <p>Valid values: <code>true</code> | <code>false</code>\n         </p>"}))
    ModifyReplicationGroupMessage.add_member(:multi_az_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZEnabled', traits: {"smithy.api#documentation" => "<p>A flag to indicate MultiAZ is enabled.</p>"}))
    ModifyReplicationGroupMessage.add_member(:node_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NodeGroupId', traits: {"smithy.api#deprecated" => {}, "smithy.api#documentation" => "<p>Deprecated. This parameter is not used.</p>"}))
    ModifyReplicationGroupMessage.add_member(:cache_security_group_names, Smithy::Schema::Shapes::ShapeRef.new(shape: CacheSecurityGroupNameList, location_name: 'CacheSecurityGroupNames', traits: {"smithy.api#documentation" => "<p>A list of cache security group names to authorize for the clusters in this replication\n            group. This change is asynchronously applied as soon as possible.</p>\n         <p>This parameter can be used only with replication group containing clusters running\n            outside of an Amazon Virtual Private Cloud (Amazon VPC).</p>\n         <p>Constraints: Must contain no more than 255 alphanumeric characters. Must not be\n                <code>Default</code>.</p>"}))
    ModifyReplicationGroupMessage.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdsList, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>Specifies the VPC Security Groups associated with the clusters in the replication\n            group.</p>\n         <p>This parameter can be used only with replication group containing clusters running in\n            an Amazon Virtual Private Cloud (Amazon VPC).</p>"}))
    ModifyReplicationGroupMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>Specifies the weekly time range during which maintenance on the cluster is performed.\n            It is specified as a range in the format ddd:hh24:mi-ddd:hh24:mi (24H Clock UTC). The\n            minimum maintenance window is a 60 minute period.</p>\n         <p>Valid values for <code>ddd</code> are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>sun</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mon</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>tue</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>wed</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>thu</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>fri</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sat</code>\n               </p>\n            </li>\n         </ul>\n         <p>Example: <code>sun:23:00-mon:01:30</code>\n         </p>"}))
    ModifyReplicationGroupMessage.add_member(:notification_topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NotificationTopicArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon SNS topic to which notifications are\n            sent.</p>\n         <note>\n            <p>The Amazon SNS topic owner must be same as the replication group owner. </p>\n         </note>"}))
    ModifyReplicationGroupMessage.add_member(:cache_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the cache parameter group to apply to all of the clusters in this\n            replication group. This change is asynchronously applied as soon as possible for\n            parameters when the <code>ApplyImmediately</code> parameter is specified as\n                <code>true</code> for this request.</p>"}))
    ModifyReplicationGroupMessage.add_member(:notification_topic_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NotificationTopicStatus', traits: {"smithy.api#documentation" => "<p>The status of the Amazon SNS notification topic for the replication group.\n            Notifications are sent only if the status is <code>active</code>.</p>\n         <p>Valid values: <code>active</code> | <code>inactive</code>\n         </p>"}))
    ModifyReplicationGroupMessage.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ApplyImmediately', traits: {"smithy.api#documentation" => "<p>If <code>true</code>, this parameter causes the modifications in this request and any\n            pending modifications to be applied, asynchronously and as soon as possible, regardless\n            of the <code>PreferredMaintenanceWindow</code> setting for the replication group.</p>\n         <p>If <code>false</code>, changes to the nodes in the replication group are applied on\n            the next maintenance reboot, or the next failure reboot, whichever occurs first.</p>\n         <p>Valid values: <code>true</code> | <code>false</code>\n         </p>\n         <p>Default: <code>false</code>\n         </p>"}))
    ModifyReplicationGroupMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>Modifies the engine listed in a replication group message. The options are redis, memcached or valkey.</p>"}))
    ModifyReplicationGroupMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The upgraded version of the cache engine to be run on the clusters in the replication\n            group.</p>\n         <p>\n            <b>Important:</b> You can upgrade to a newer engine version\n            (see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/SelectEngine.html#VersionManagement\">Selecting\n                a Cache Engine and Version</a>), but you cannot downgrade to an earlier engine\n            version. If you want to use an earlier engine version, you must delete the existing\n            replication group and create it anew with the earlier engine version. </p>"}))
    ModifyReplicationGroupMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p> If you are running Valkey or Redis OSS engine version 6.0 or later, set this parameter to yes if\n            you want to opt-in to the next auto minor version upgrade campaign. This parameter is\n            disabled for previous versions.  </p>"}))
    ModifyReplicationGroupMessage.add_member(:snapshot_retention_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SnapshotRetentionLimit', traits: {"smithy.api#documentation" => "<p>The number of days for which ElastiCache retains automatic node group (shard)\n            snapshots before deleting them. For example, if you set\n                <code>SnapshotRetentionLimit</code> to 5, a snapshot that was taken today is\n            retained for 5 days before being deleted.</p>\n         <p>\n            <b>Important</b> If the value of SnapshotRetentionLimit is\n            set to zero (0), backups are turned off.</p>"}))
    ModifyReplicationGroupMessage.add_member(:snapshot_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotWindow', traits: {"smithy.api#documentation" => "<p>The daily time range (in UTC) during which ElastiCache begins taking a daily snapshot\n            of the node group (shard) specified by <code>SnapshottingClusterId</code>.</p>\n         <p>Example: <code>05:00-09:00</code>\n         </p>\n         <p>If you do not specify this parameter, ElastiCache automatically chooses an appropriate\n            time range.</p>"}))
    ModifyReplicationGroupMessage.add_member(:cache_node_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CacheNodeType', traits: {"smithy.api#documentation" => "<p>A valid cache node type that you want to scale this replication group to.</p>"}))
    ModifyReplicationGroupMessage.add_member(:auth_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AuthToken', traits: {"smithy.api#documentation" => "<p>Reserved parameter. The password used to access a password protected server. This\n            parameter must be specified with the <code>auth-token-update-strategy </code> parameter.\n            Password constraints:</p>\n         <ul>\n            <li>\n               <p>Must be only printable ASCII characters</p>\n            </li>\n            <li>\n               <p>Must be at least 16 characters and no more than 128 characters in\n                    length</p>\n            </li>\n            <li>\n               <p>Cannot contain any of the following characters: '/', '\"', or '@', '%'</p>\n            </li>\n         </ul>\n         <p> For more information, see AUTH password at <a href=\"http://redis.io/commands/AUTH\">AUTH</a>.</p>"}))
    ModifyReplicationGroupMessage.add_member(:auth_token_update_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: AuthTokenUpdateStrategyType, location_name: 'AuthTokenUpdateStrategy', traits: {"smithy.api#documentation" => "<p>Specifies the strategy to use to update the AUTH token. This parameter must be\n            specified with the <code>auth-token</code> parameter. Possible values:</p>\n         <ul>\n            <li>\n               <p>ROTATE - default, if no update strategy is provided</p>\n            </li>\n            <li>\n               <p>SET - allowed only after ROTATE</p>\n            </li>\n            <li>\n               <p>DELETE - allowed only when transitioning to RBAC</p>\n            </li>\n         </ul>\n         <p> For more information, see <a href=\"http://docs.aws.amazon.com/AmazonElastiCache/latest/dg/auth.html\">Authenticating Users with AUTH</a>\n         </p>"}))
    ModifyReplicationGroupMessage.add_member(:user_group_ids_to_add, Smithy::Schema::Shapes::ShapeRef.new(shape: UserGroupIdList, location_name: 'UserGroupIdsToAdd', traits: {"smithy.api#documentation" => "<p>The ID of the user group you are associating with the replication group.</p>"}))
    ModifyReplicationGroupMessage.add_member(:user_group_ids_to_remove, Smithy::Schema::Shapes::ShapeRef.new(shape: UserGroupIdList, location_name: 'UserGroupIdsToRemove', traits: {"smithy.api#documentation" => "<p>The ID of the user group to disassociate from the replication group, meaning the users\n            in the group no longer can access the replication group.</p>"}))
    ModifyReplicationGroupMessage.add_member(:remove_user_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'RemoveUserGroups', traits: {"smithy.api#documentation" => "<p>Removes the user group associated with this replication group.</p>"}))
    ModifyReplicationGroupMessage.add_member(:log_delivery_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: LogDeliveryConfigurationRequestList, location_name: 'LogDeliveryConfigurations', traits: {"smithy.api#documentation" => "<p>Specifies the destination, format and type of the logs.</p>"}))
    ModifyReplicationGroupMessage.add_member(:ip_discovery, Smithy::Schema::Shapes::ShapeRef.new(shape: IpDiscovery, location_name: 'IpDiscovery', traits: {"smithy.api#documentation" => "<p>The network type you choose when modifying a cluster, either <code>ipv4</code> |\n            <code>ipv6</code>. IPv6 is supported for workloads using Valkey 7.2 and above, Redis OSS engine version 6.2\n            to 7.1 and Memcached engine version 1.6.6 and above on all instances built on the <a href=\"http://aws.amazon.com/ec2/nitro/\">Nitro system</a>.</p>"}))
    ModifyReplicationGroupMessage.add_member(:transit_encryption_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'TransitEncryptionEnabled', traits: {"smithy.api#documentation" => "<p>A flag that enables in-transit encryption when set to true. If you are enabling\n            in-transit encryption for an existing cluster, you must also set\n                <code>TransitEncryptionMode</code> to <code>preferred</code>.</p>"}))
    ModifyReplicationGroupMessage.add_member(:transit_encryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitEncryptionMode, location_name: 'TransitEncryptionMode', traits: {"smithy.api#documentation" => "<p>A setting that allows you to migrate your clients to use in-transit encryption, with\n            no downtime.</p>\n         <p>You must set <code>TransitEncryptionEnabled</code> to <code>true</code>, for your\n            existing cluster, and set <code>TransitEncryptionMode</code> to <code>preferred</code>\n            in the same request to allow both encrypted and unencrypted connections at the same\n            time. Once you migrate all your Valkey or Redis OSS clients to use encrypted connections you can set\n            the value to <code>required</code> to allow encrypted connections only.</p>\n         <p>Setting <code>TransitEncryptionMode</code> to <code>required</code> is a two-step\n            process that requires you to first set the <code>TransitEncryptionMode</code> to\n                <code>preferred</code>, after that you can set <code>TransitEncryptionMode</code> to\n                <code>required</code>. </p>"}))
    ModifyReplicationGroupMessage.add_member(:cluster_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ClusterMode, location_name: 'ClusterMode', traits: {"smithy.api#documentation" => "<p>Enabled or Disabled. To modify cluster mode from Disabled to Enabled, you must first\n            set the cluster mode to Compatible. Compatible mode allows your Valkey or Redis OSS clients to connect\n            using both cluster mode enabled and cluster mode disabled. After you migrate all Valkey or Redis OSS\n            clients to use cluster mode enabled, you can then complete cluster mode configuration\n            and set the cluster mode to Enabled.</p>"}))
    ModifyReplicationGroupMessage.type = Types::ModifyReplicationGroupMessage
