    ModifyReplicationGroupShardConfigurationMessage.add_member(:replication_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationGroupId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Valkey or Redis OSS (cluster mode enabled) cluster (replication group) on which the\n            shards are to be configured.</p>", "smithy.api#required" => {}}))
    ModifyReplicationGroupShardConfigurationMessage.add_member(:node_group_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'NodeGroupCount', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The number of node groups (shards) that results from the modification of the shard\n            configuration.</p>", "smithy.api#required" => {}}))
    ModifyReplicationGroupShardConfigurationMessage.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ApplyImmediately', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Indicates that the shard reconfiguration process begins immediately. At present, the\n            only permitted value for this parameter is <code>true</code>.</p>\n         <p>Value: true</p>", "smithy.api#required" => {}}))
    ModifyReplicationGroupShardConfigurationMessage.add_member(:resharding_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ReshardingConfigurationList, location_name: 'ReshardingConfiguration', traits: {"smithy.api#documentation" => "<p>Specifies the preferred availability zones for each node group in the cluster. If the\n            value of <code>NodeGroupCount</code> is greater than the current number of node groups\n            (shards), you can use this parameter to specify the preferred availability zones of the\n            cluster's shards. If you omit this parameter ElastiCache selects availability zones for\n            you.</p>\n         <p>You can specify this parameter only if the value of <code>NodeGroupCount</code> is\n            greater than the current number of node groups (shards).</p>"}))
    ModifyReplicationGroupShardConfigurationMessage.add_member(:node_groups_to_remove, Smithy::Schema::Shapes::ShapeRef.new(shape: NodeGroupsToRemoveList, location_name: 'NodeGroupsToRemove', traits: {"smithy.api#documentation" => "<p>If the value of <code>NodeGroupCount</code> is less than the current number of node\n            groups (shards), then either <code>NodeGroupsToRemove</code> or\n                <code>NodeGroupsToRetain</code> is required. <code>NodeGroupsToRemove</code> is a\n            list of <code>NodeGroupId</code>s to remove from the cluster.</p>\n         <p>ElastiCache will attempt to remove all node groups listed by\n                <code>NodeGroupsToRemove</code> from the cluster.</p>"}))
