    ReplicationGroup.add_member(:data_tiering, Smithy::Schema::Shapes::ShapeRef.new(shape: DataTieringStatus, location_name: 'DataTiering', traits: {"smithy.api#documentation" => "<p>Enables data tiering. Data tiering is only supported for replication groups using the\n            r6gd node type. This parameter must be set to true when using r6gd nodes. For more\n            information, see <a href=\"https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/data-tiering.html\">Data tiering</a>.</p>"}))
    ReplicationGroup.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>If you are running Valkey 7.2 and above, or Redis OSS engine version 6.0 and above, set this parameter to yes if you\n            want to opt-in to the next auto minor version upgrade campaign. This parameter is\n            disabled for previous versions. </p>"}))
    ReplicationGroup.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkType, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>Must be either <code>ipv4</code> | <code>ipv6</code> | <code>dual_stack</code>. IPv6\n            is supported for workloads using Valkey 7.2 and above, Redis OSS engine version 6.2\n            to 7.1 or Memcached engine version 1.6.6 and above on all instances built on the <a href=\"http://aws.amazon.com/ec2/nitro/\">Nitro system</a>.</p>"}))
    ReplicationGroup.add_member(:ip_discovery, Smithy::Schema::Shapes::ShapeRef.new(shape: IpDiscovery, location_name: 'IpDiscovery', traits: {"smithy.api#documentation" => "<p>The network type you choose when modifying a cluster, either <code>ipv4</code> |\n            <code>ipv6</code>. IPv6 is supported for workloads using Valkey 7.2 and above, Redis OSS engine version 6.2\n            to 7.1 or Memcached engine version 1.6.6 and above on all instances built on the <a href=\"http://aws.amazon.com/ec2/nitro/\">Nitro system</a>.</p>"}))
    ReplicationGroup.add_member(:transit_encryption_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitEncryptionMode, location_name: 'TransitEncryptionMode', traits: {"smithy.api#documentation" => "<p>A setting that allows you to migrate your clients to use in-transit encryption, with\n            no downtime.</p>"}))
    ReplicationGroup.add_member(:cluster_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ClusterMode, location_name: 'ClusterMode', traits: {"smithy.api#documentation" => "<p>Enabled or Disabled. To modify cluster mode from Disabled to Enabled, you must first\n            set the cluster mode to Compatible. Compatible mode allows your Valkey or Redis OSS clients to connect\n            using both cluster mode enabled and cluster mode disabled. After you migrate all Valkey or Redis OSS \n            clients to use cluster mode enabled, you can then complete cluster mode configuration\n            and set the cluster mode to Enabled.</p>"}))
